// Üretilen dosya: tool/ozgun/uret.py. Sınav Hazırlık · Sözel mantık ve akıl yürütme (sıralama, eşleştirme, koşullu çıkarım; her soru kendi verisini içerir) (zor).
const ozExam4Zor = <(String, String, List<String>, String)>[
  ('Altı yüzücünün katıldığı bir yarışta Gül dördüncü olmuş, Can da Gül\'ün hemen önünde bitirmiştir. Nur ile Oya art arda gelmiş, Ali ise Efe\'den sonra bitirmiştir. Buna göre aşağıdakilerden hangisi kesinlikle yanlıştır?', 'Ali beşinci olmuştur.', ['Efe birinci olmuştur.', 'Nur sonuncu sırada bitirmiştir.', 'Oya ikinci olmuştur.'], 'Can 3., Gül 4. olduğundan Nur-Oya ikilisi ya 1-2 ya da 5-6. sıraları alır; Efe-Ali de kalan ikiliyi bu sırayla doldurur. Ali yalnızca 2. ya da 6. olabilir, beşinci olamaz.'),
  ('Altı kişi yuvarlak bir masanın çevresine eşit aralıklarla, yüzleri masaya dönük oturmuştur: Ali, Can, Ece, Nur, Oya ve Umut. Ali, Nur\'un tam karşısındadır. Can, Ali\'nin hemen sağındadır. Oya, Can\'ın tam karşısındadır. Ece, Nur\'un yanında değildir. Umut\'un iki yanında kimler oturur?', 'Nur ile Can', ['Ali ile Oya', 'Ece ile Nur', 'Can ile Ali'], 'Ali\'yi sabitleyince Nur karşıya, Can Ali\'nin sağına, Oya da Can\'ın karşısına (Nur\'un yanına) gelir. Boş kalan iki yerden Nur\'a bitişik olmayana Ece, diğerine Umut oturur; Umut\'un yanları Nur ve Can\'dır.'),
  ('Bir toplantı için şunlar bilinmektedir: Leyla gelirse Murat da gelir. Murat gelirse Nazlı gelmez. Nazlı gelmezse Okan gelir. Toplantıya Okan gelmemiştir. Buna göre hangisi kesinlikle doğrudur?', 'Leyla toplantıya gelmemiştir.', ['Murat toplantıya gelmiştir.', 'Nazlı da Murat da toplantıya gelmemiştir.', 'Leyla toplantıya gelmiştir.'], 'Okan gelmediyse Nazlı gelmiştir; Nazlı geldiyse Murat gelmemiştir; Murat gelmediyse Leyla da gelmemiştir. Zincir geriye doğru izlenir.'),
  ('Şu öncüller doğrudur: Bütün sabah koşucuları erken kalkar. Erken kalkanların hiçbiri gece yarısı film izlemez. Bazı üniversite öğrencileri sabah koşucusudur. Buna göre hangisi kesinlikle doğrudur?', 'Bazı üniversite öğrencileri gece yarısı film izlemez.', ['Hiçbir üniversite öğrencisi film izlemez.', 'Bütün üniversite öğrencilerinin erken kalktığı kesindir.', 'Gece film izleyen herkes öğrencidir.'], 'Sabah koşucusu olan öğrenciler erken kalkar; erken kalkanlar da gece yarısı film izlemez. Böylece en az bazı öğrenciler için bu yargı kesindir.'),
  ('“Bütün robot oyuncaklar pille çalışır.” ve “Bazı oyuncaklar pille çalışmaz.” bilgilerinden hangisi kesinlikle çıkar?', 'Bazı oyuncaklar robot oyuncak değildir.', ['Bazı robot oyuncaklar pilsizdir.', 'Pille çalışan her oyuncağın bir robot olduğu anlaşılır.', 'Hiçbir oyuncak robot değildir.'], 'Pille çalışmayan oyuncaklar robot olamaz, çünkü robotların hepsi pille çalışır. Demek ki en az bazı oyuncaklar robot değildir.'),
  ('Bir akıl yürütmede öncül “Bütün bal arıları polen taşır.”, sonuç ise “Bazı uçan canlılar polen taşır.” biçimindedir. Sonucun geçerli olması için hangi öncülün eklenmesi gerekir?', 'Bazı uçan canlılar bal arısıdır.', ['Polen taşıyan her canlı uçar.', 'Bazı bal arıları uçamaz.', 'Hiçbir uçan canlı bal arısı değildir.'], 'Uçan canlılardan bazılarının bal arısı olduğu bilinirse, bunlar polen taşıyacağından sonuç zorunlu hâle gelir.'),
  ('“Hiçbir kare üçgen değildir.” ve “Bütün kareler dörtgendir.” önermelerinden hangisi kesinlikle çıkar?', 'Bazı dörtgenler üçgen değildir.', ['Hiçbir dörtgen üçgen değildir.', 'Bütün dörtgenlerin kare olduğu sonucu çıkar.', 'Bazı üçgenler dörtgendir.'], 'Kare olan dörtgenler üçgen değildir; böylece en az bazı dörtgenler için bu yargı kesinleşir. Bütün dörtgenler hakkında ise bilgi yoktur.'),
  ('Bir şirketteki çalışanların yarıdan fazlası İngilizce, yarıdan fazlası da Almanca bilmektedir. Buna göre hangisi kesinlikle doğrudur?', 'En az bir çalışan iki dili birden bilir.', ['Her çalışan iki dili de bilir.', 'Her çalışan bu iki dilden en az birini bilmektedir.', 'İngilizce bilen herkes Almanca da bilir.'], 'İki grup ayrık olsaydı toplamları çalışan sayısını aşardı. Bu yüzden iki grubun en az bir ortak kişisi olmalıdır.'),
  ('Bir adada yaşayanlar ya doğrucudur (her zaman doğruyu söyler) ya da yalancıdır (her zaman yalan söyler). Ayla “Bulut yalancıdır.”, Bulut “Ceyda yalancıdır.”, Ceyda ise “Ayla da Bulut da yalancıdır.” diyor. Bu üç kişiden kaçı doğrucudur?', '1', ['0', '2', '3'], 'Ceyda doğrucu olsaydı Ayla ve Bulut yalancı olurdu; ama yalancı Bulut\'un sözü doğru çıkardı. Ceyda yalancıdır; Bulut doğru söyler, Ayla yalan söyler. Yalnızca Bulut doğrucudur.'),
  ('Sınıf panosunu kim boyadı? Arda: “Banu ya da Cem boyadı.” Banu: “Ben boyamadım.” Cem: “Duru boyadı.” Duru: “Ben boyamadım.” Panoyu tek kişi boyamış ve dört kişiden yalnızca biri yalan söylemiştir. Panoyu kim boyamıştır?', 'Cem', ['Arda', 'Banu', 'Duru'], 'Cem ile Duru\'nun sözleri birbirine zıttır, bu yüzden yalancı bu ikisinden biridir ve Arda ile Banu doğrudur. Arda ve Banu\'ya göre boyayan Cem\'dir; yalan söyleyen de Cem olur.'),
  ('Bir yol ikiye ayrılıyor ve köye yalnızca biri gidiyor. Yolun başında biri her zaman doğru, diğeri her zaman yalan söyleyen iki bekçi var; hangisinin hangisi olduğu bilinmiyor. Bekçilerden birine “Diğer bekçiye köyün yolunu sorsam hangisini gösterirdi?” diye soruluyor ve sağ yolu gösteriyor. Köye giden yol hangisidir?', 'Sol yol', ['Sağ yol', 'Bu yanıttan anlaşılamaz', 'İki yol da köye çıkar'], 'Soru hangi bekçiye sorulursa sorulsun yanıt, bir doğru bir yalan süzgecinden geçtiği için yanlış yolu gösterir. Bu yüzden gösterilen yolun tersi doğrudur.'),
  ('Pastadan bir dilimi Ece, Fikret, Gamze ve Hande\'den biri gizlice yemiştir. Ece: “Fikret yedi.” Fikret: “Hande yedi.” Gamze: “Ben yemedim.” Hande: “Fikret yalan söylüyor.” Dört sözden yalnızca biri doğruysa pastayı kim yemiştir?', 'Gamze', ['Ece', 'Fikret', 'Hande'], 'Fikret ile Hande\'nin sözleri birbirine zıt olduğundan doğru olan tek söz bu ikisinden biridir. O hâlde Gamze\'nin sözü yanlıştır ve pastayı Gamze yemiştir; bu durumda doğru söyleyen yalnızca Hande olur.'),
  ('Sinan pazartesi, salı ve çarşamba günleri hep yalan, haftanın diğer günlerinde hep doğru söyler. Bir gün “Dün yalan söylediğim günlerden biriydi.” demiştir. Bu söz hangi günlerde söylenmiş olabilir?', 'Pazartesi ya da perşembe', ['Yalnızca perşembe', 'Salı ya da çarşamba', 'Yalnızca pazar ya da pazartesi'], 'Doğru söylediği bir günde sözün doğru olması için dünün yalan günü olması gerekir: perşembe. Yalan günlerinde sözün yanlış olması için dünün doğru günü olması gerekir: pazartesi.'),
  ('Bir adada yaşayanlar ya doğrucudur (her zaman doğruyu söyler) ya da yalancıdır (her zaman yalan söyler). Ozan “Pınar yalancıdır.”, Pınar ise “Ozan ile Rüya aynı türdendir.” diyor. Rüya hiçbir şey söylemiyor. Buna göre hangisi kesinlikle doğrudur?', 'Rüya yalancıdır.', ['Ozan doğrucudur.', 'Pınar bir yalancıdır.', 'Rüya doğrucudur.'], 'Ozan\'ın sözü nedeniyle Ozan ile Pınar farklı türdendir. Ozan doğrucuysa Pınar yalancıdır ve Rüya, Ozan\'dan farklı yani yalancıdır; Ozan yalancıysa Pınar doğrucudur ve Rüya, Ozan gibi yalancıdır.'),
  ('Bir adada yaşayanlar ya doğrucudur (her zaman doğruyu söyler) ya da yalancıdır (her zaman yalan söyler). Kaan “Aramızda tam bir yalancı var.”, Lale “Aramızda tam iki yalancı var.”, Mine “Üçümüz de yalancıyız.” diyor. Doğrucu olan kimdir ya da kimlerdir?', 'Lale', ['Kaan', 'Mine', 'Kaan ile Mine'], 'Sözler birbirini dışladığından en çok biri doğrudur; dolayısıyla en az iki yalancı vardır. Mine doğrucu olamaz (kendini yalancı sayar). Tam iki yalancı varsa Lale\'nin sözü doğrudur ve tutarlı tek durum budur.'),
  ('Bir adada yaşayanlar ya doğrucudur (her zaman doğruyu söyler) ya da yalancıdır (her zaman yalan söyler). Tuna, yanındaki Ufuk için “Ya ben yalancıyım ya da Ufuk doğrucudur.” diyor (ikisinin birden doğru olması da kabul ediliyor). Buna göre hangisi doğrudur?', 'İkisi de doğrucudur.', ['Tuna yalancı, Ufuk doğrucudur.', 'İkisi de birer yalancıdır.', 'Tuna doğrucu, Ufuk yalancıdır.'], 'Tuna yalancı olsaydı “ya ben yalancıyım” kısmı doğru, dolayısıyla bütün söz doğru olurdu; çelişki. Tuna doğrucudur; o zaman ilk kısım yanlış olduğundan Ufuk doğrucu olmalıdır.'),
  ('Bir adada yaşayanlar ya doğrucudur (her zaman doğruyu söyler) ya da yalancıdır (her zaman yalan söyler). Bir araya gelen üç adalıdan her biri “Buradaki diğer iki kişi yalancıdır.” diyor. Buna göre hangisi kesinlikle doğrudur?', 'Tam olarak bir kişi doğrucudur.', ['Üçü de yalancıdır.', 'Tam olarak iki kişi doğrucudur.', 'Üçünün de doğrucu olduğu ortaya çıkar.'], 'Hiç doğrucu yoksa sözler doğru çıkar, çelişki olur. İki doğrucu varsa biri diğerini yalancı demiş olur, yine çelişki. Yalnızca tek doğrucunun bulunduğu durum tutarlıdır; ama kimin olduğu bilinemez.'),
  ('Türk alfabesinin 29 harfi (A B C Ç D E F G Ğ H I İ J K L M N O Ö P R S Ş T U Ü V Y Z) kullanılıyor. Bir şifrede sözcük önce tersten yazılıyor, ardından her harf alfabede kendisinden hemen önce gelen harfle değiştiriliyor. ÇİÇEK sözcüğünün şifreli hâli nedir?', 'JDCIC', ['LFDJD', 'JECİC', 'KEÇİÇ'], 'Tersten yazılınca KEÇİÇ olur. Her harfi bir geri kaydırınca K→J, E→D, Ç→C, İ→I, Ç→C ve sonuç JDCIC\'dir.'),
  ('Üç kutunun birinde yalnız elma, birinde yalnız portakal, birinde ise karışık meyve vardır. Kutulara “Elma”, “Portakal” ve “Karışık” etiketleri yapıştırılmış ama etiketlerin üçü de yanlış kutudadır. Tek bir kutudan bakmadan tek bir meyve çekerek bütün kutuları doğru etiketlemek için hangi kutudan çekilmelidir?', '“Karışık” etiketli kutudan', ['“Elma” etiketli kutudan', '“Portakal” etiketli kutudan', 'Hangi kutudan çekildiği fark etmez'], '“Karışık” etiketli kutu karışık olamaz; çıkan meyve o kutunun içeriğini kesin olarak gösterir. Ardından kalan iki kutunun etiketleri de yanlış olma koşulundan tek biçimde belirlenir.'),
  ('Bir sınıfta 30 öğrenci vardır; bunların 16\'sı kız, 14\'ü erkektir. Sınıfta gözlük takan 10 öğrenci bulunmaktadır. Buna göre hangisi kesinlikle doğrudur?', 'En az dört erkek öğrenci gözlük takmaz.', ['Gözlük takanlardan en az biri kızdır.', 'Kız öğrencilerin çoğu gözlük takmamaktadır.', 'Sınıfta gözlük takan en az bir erkek öğrenci vardır.'], 'Gözlüklülerin hepsi erkek olsa bile 14 erkekten 10\'u gözlüklü olur ve 4 erkek gözlüksüz kalır. Diğer seçenekler gözlüklülerin dağılımına göre yanlış olabilir.'),
  ('Bir öğrencinin pazartesi günü art arda dört dersi vardır: matematik, fizik, kimya ve biyoloji. Fizik, matematikten hemen sonra gelir. Kimya ilk ders, biyoloji de son ders değildir. Buna göre hangisi kesinlikle doğrudur?', 'Biyoloji, kimyadan önce yapılır.', ['Matematik günün ilk dersi olarak yapılır.', 'Kimya günün en son dersidir.', 'Fizik ikinci sırada yapılır.'], 'Olası sıralamalar M-F-B-K, B-M-F-K ve B-K-M-F\'dir. Üçünde de biyoloji kimyadan öncedir; diğer seçenekler bazı sıralamalarda yanlıştır.'),
  ('Bir öğretmen pazartesi, salı ve çarşamba günlerine her gün iki etkinlik olacak şekilde altı etkinlik yerleştiriyor: anket, bilmece, çizim, drama, ezgi ve fotoğraf. Anket ile bilmece aynı güne konmayacak, çizim dramanın ertesi gününe gelecek, ezgi pazartesi yapılmayacak, fotoğraf da çarşambaya konacaktır. Pazartesi günü kesinlikle hangi etkinlik yapılır?', 'Drama', ['Anket', 'Bilmece', 'Çizim'], 'Çizim-drama ikilisi salı-çarşamba olsaydı çarşamba fotoğrafla birlikte dolup ezgi pazartesiye kalırdı. Bu yüzden drama pazartesi, çizim salıdır; anket ve bilmeceden biri pazartesiye gelir ama hangisi olduğu belirsizdir.'),
  ('Bir öğrenci satranç, keman, yüzme, resim ve tiyatro kurslarından tam üçünü seçecektir. Keman seçerse resim seçemez. Yüzme seçerse tiyatroyu da seçmelidir. Satranç seçmezse keman seçmelidir. Kurallara uyan her seçimde hangi kurs kesinlikle yer alır?', 'Tiyatro kursu', ['Satranç kursu', 'Keman kursu', 'Yüzme kursu'], 'Tiyatro seçilmezse yüzme de seçilemez; geriye satranç, keman ve resim kalır, ama keman ile resim birlikte olamaz. Bu yüzden tiyatrosuz üç kurs seçmek imkânsızdır.'),
  ('Üç katlı bir pansiyonun her katında biri solda biri sağda iki oda vardır. Ada, Bora, Cem, Defne, Ece ve Fırat birer odada kalıyor. Ada ile Bora aynı kattadır. Cem 3. kattadır. Defne, Ece\'nin tam altındaki odadadır. Fırat sol taraftaki, Ece sağ taraftaki bir odada kalır. Fırat hangi odadadır?', '2. katın sol odasında', ['1. katın sol odasında', '3. katın sol odasında', '2. katın sağ tarafındaki odada'], 'Ada-Bora bir katı tümüyle doldurur, Cem 3. kattadır. Defne Ece\'nin altında olduğundan Ece 3. katın sağında, Defne 2. katın sağındadır. Ada-Bora 1. katı alır ve Fırat 2. katın soluna yerleşir.'),
  ('Üç takımlı bir grupta her takım diğer ikisiyle birer maç yapar; galibiyete 3, beraberliğe 1, yenilgiye 0 puan verilir. Maçlar bittiğinde X ve Y takımlarının ikisi de 4 puan toplamıştır. Z takımı kaç puan toplamıştır?', '0', ['1', '2', '3'], '4 puan bir galibiyet ve bir beraberlik demektir. X-Y maçı bir taraf kazanarak bitseydi kaybeden takım 4 puana ulaşamazdı; bu maç berabere bitmiş, X ve Y, Z\'yi yenmiştir.'),
  ('Bir torbada 4 kırmızı, 6 mavi ve 3 yeşil bilye vardır. Bakmadan en az kaç bilye çekilirse her renkten en az bir bilye çekilmiş olması garanti edilir?', '11', ['10', '4', '13'], 'En kötü durumda önce 6 mavi ve 4 kırmızı bilye çekilir; bu 10 bilyede yeşil yoktur. 11. bilye kesinlikle yeşil olur.'),
  ('Dört kişi gece bir köprüyü tek fenerle geçecektir. Köprüde aynı anda en çok iki kişi bulunabilir ve her geçişte fener taşınmalıdır. Kişiler köprüyü sırasıyla 1, 2, 5 ve 10 dakikada geçer; ikili geçişte yavaş olanın hızına uyulur. Dördünün karşıya geçmesi en az kaç dakika sürer?', '17', ['19', '18', '21'], '1 ve 2 geçer (2), 1 döner (1), 5 ve 10 geçer (10), 2 döner (2), 1 ve 2 geçer (2): toplam 17 dakika. En yavaş ikiliyi birlikte göndermek süreyi kısaltır.'),
  ('Bir kişinin elinde 3 litrelik ve 5 litrelik işaretsiz iki boş kap ile sınırsız su vardır. Bir kabı doldurmak, boşaltmak ya da birinden ötekine dökmek birer işlem sayılırsa, kaplardan birinde tam 4 litre su elde etmek için en az kaç işlem gerekir?', '6', ['4', '5', '7'], '5\'liği doldur, 3\'lüğe dök (5\'likte 2 kalır), 3\'lüğü boşalt, 2 litreyi 3\'lüğe dök, 5\'liği doldur, 3\'lüğü doldurana kadar dök: 5\'likte 4 litre kalır.'),
  ('Her kartın bir yüzünde bir harf, öbür yüzünde bir sayı vardır. Kural: “Bir kartın bir yüzünde ünlü harf varsa öbür yüzünde çift sayı vardır.” Masada A, K, 4 ve 7 yazan yüzleri görünen dört kart bulunuyor. Kuralın doğru olup olmadığını anlamak için en az hangi kartların çevrilmesi gerekir?', 'A ve 7', ['A ve 4', 'Yalnızca A', 'A, 4 ve 7'], 'A\'nın arkası tek sayıysa kural çiğnenir; 7\'nin arkası ünlüyse de çiğnenir. 4\'ün arkasında ne olursa olsun kural bozulmaz; K ise kuralın kapsamı dışındadır.'),
  ('Bir festivalde “Konser alanına giren herkesin bilekliği olmalıdır.” kuralı uygulanıyor. Görevli dört kişiyi görüyor: alanın içinde biri, alanın dışında biri, bilekliği olan biri ve bilekliği olmayan biri. Kuralın çiğnenip çiğnenmediğini anlamak için hangi iki kişiyi kontrol etmelidir?', 'İçerideki kişiyi ve bilekliği olmayanı', ['Dışarıdaki kişiyi ve bilekliği olanı', 'İçerideki kişiyi ve bilekliği olanı', 'Dışarıdaki kişiyi ve bilekliği olmayanı'], 'İçerideki kişinin bilekliği olup olmadığına, bilekliği olmayan kişinin de içeride olup olmadığına bakılmalıdır. Dışarıdaki ya da bilekliği olan kişi kuralı çiğneyemez.'),
  ('Üstten alta 1\'den 6\'ya kadar sıralı altı kartlık bir destede şu işlem tekrarlanıyor: en üstteki kart masaya atılır, ardından yeni en üstteki kart destenin en altına konur. Deste bitene kadar böyle devam edilirse en son masaya atılan kart hangisidir?', '4', ['6', '2', '5'], 'Atılma sırası 1, 3, 5, 2, 6, 4 olur. Her turda bir kart atılıp bir kart alta gönderildiği için adım adım izlemek gerekir.'),
  ('Pelin, Rıza, Sami, Tolga ve Uğur bir kuyruğa giriyor. Rıza, Pelin\'den öndedir. Sami ile Tolga arasında tam bir kişi vardır. Uğur ne en baştadır ne de en sonda. Buna göre aşağıdakilerden hangisi olamaz?', 'Pelin üçüncü sıradadır.', ['Uğur üçüncü sıradadır.', 'Rıza ikinci sıradadır.', 'Pelin dördüncü sıradadır.'], 'Pelin üçüncü olursa Rıza önde, Uğur ortada olmalı; Sami-Tolga arasında bir kişi bırakacak iki yer kalmaz. Diğer üç durum ise uygun dizilişlerle sağlanabilir.'),
  ('Efe, Gaye, Hilal ve İlker bir yarışı farklı sıralarda bitirmiştir. Efe, Gaye\'den; Hilal de İlker\'den önce bitirmiştir. Bitiş sıralamasının tek biçimde belirlenebilmesi için aşağıdaki bilgilerden hangisi tek başına yeterlidir?', 'Gaye, Hilal\'den önce bitirmiştir.', ['Efe yarışı birinci sırada bitirmiştir.', 'İlker yarışı sonuncu olarak bitirmiştir.', 'Hilal yarışı ikinci sırada bitirmiştir.'], 'Gaye Hilal\'den önceyse Efe-Gaye-Hilal-İlker zinciri tek sıralamayı verir. Diğer bilgilerin her biriyle iki ya da üç farklı sıralama mümkündür.'),
  ('Altı katlı bir binada Kaya, Tan, Uçar, Ateş, Oral ve Polat aileleri farklı katlarda oturur. Kaya ailesi Tanlardan üst kattadır. Uçar ile Ateş aileleri komşu katlardadır. Oral ailesi 6. kattadır. Polat ailesi Uçarlardan alt kattadır. Tanlar 1. katta oturmaz. Buna göre hangisi kesinlikle yanlıştır?', 'Tanlar 3. katta oturur.', ['Kayalar 3. katta oturur.', 'Uçarlar 4. katta oturur.', 'Ateşler 2. katta oturur.'], 'Polat ailesi her durumda 1. kata düşer. Tanlar 3. kata yerleşirse Kayalar üstte, Uçar-Ateş ikilisi de komşu iki kat bulmak zorundadır; 2, 4 ve 5. katlar bu ikiliye ve Kayalara yetmez.'),
  ('Bir sırada Ece baştan dokuzuncu, Deniz sondan dokuzuncudur. Ece, Deniz\'in önündedir ve ikisinin arasında en az iki kişi vardır. Bu sırada en az kaç kişi bulunur?', '20', ['18', '19', '16'], 'Ece\'ye kadar 9 kişi, aradaki en az 2 kişi ve Deniz dâhil sondan 9 kişi vardır. Toplam en az 9 + 2 + 9 = 20 kişidir.'),
  ('“Yağmur yağmazsa maç oynanır.” önermesine mantıksal olarak denk olan hangisidir?', 'Maç oynanmadıysa yağmur yağmıştır.', ['Yağmur yağarsa maç kesinlikle oynanmaz.', 'Maç oynandıysa yağmur yağmamış demektir.', 'Yağmur yağmazsa maç bir gün ertelenir.'], '“p ise q” ile “q değilse p değildir” denktir. Burada p: yağmur yağmaması, q: maçın oynanmasıdır; q\'nun değili maçın oynanmaması, p\'nin değili yağmurun yağmasıdır.'),
  ('Ece, Fuat, Gül ve Halil; Adana, Bursa, Konya ve Sivas\'ta yaşıyor ve her biri tenis, yüzme, judo ya da okçuluktan farklı birini yapıyor. Ece Bursa\'da yaşar. Fuat okçulukla uğraşır ve Sivas\'ta yaşamaz. Adana\'da yaşayan tenis oynar. Judo yapan Konya\'da yaşamaz. Gül Adana\'da yaşamaz ve yüzme yapmaz. Halil judo yapmaz. Judo yapan kişi hangi kentte yaşar?', 'Sivas', ['Konya', 'Adana', 'Bursa'], 'Gül ne yüzme yapar ne de tenis (Adana\'da değil) ya da okçuluk; Gül judocudur. Judocu Konya\'da yaşamaz, Bursa Ece\'nin, Adana tenisçinindir; Gül Sivas\'ta yaşar.'),
  ('Bir sokakta soldan sağa dizili dört ev beyaz, sarı, mavi ve yeşile boyanmıştır; evlerde Kaan, Lale, Mert ve Nil oturur. Sarı ev beyaz evin hemen sağındadır. Kaan en soldaki evdedir. Nil mavi evde oturur. Yeşil ev en sağdadır. Mert\'in evi Lale\'ninkinin solundadır. Lale sarı evde oturmaz. Mert hangi renk evde oturur?', 'Sarı', ['Beyaz', 'Mavi', 'Yeşil'], 'Yeşil 4. evdir; beyaz-sarı ikilisi 1-2 ya da 2-3\'tedir. 2-3 olursa mavi 1. eve, yani Kaan\'a düşer; ama mavi Nil\'indir. Beyaz 1 (Kaan), sarı 2, mavi 3 (Nil), yeşil 4\'tür. Lale sarıda oturmadığına göre yeşilde, Mert sarıdadır.'),
  ('Oğuz, Pınar, Rana ve Sinan pazartesiden perşembeye her gün bir kişi olmak üzere okulda nöbet tutar; nöbet yerleri bahçe, kantin, koridor ve kapıdır. Pınar salı günü nöbetçidir. Kantin nöbeti perşembedir. Bahçe nöbeti pazartesidir. Oğuz\'un nöbeti pazartesi değildir ve kapıda tutulmaz. Rana koridorda nöbet tutar ve günü Sinan\'ınkinden sonradır. Oğuz hangi gün nöbet tutar?', 'Perşembe günü', ['Çarşamba günü', 'Salı günü', 'Pazartesi günü'], 'Pazartesi bahçe nöbetini Oğuz, Pınar ya da koridordaki Rana tutamaz; o gün Sinan\'dır. Rana koridorda olduğu için kantin günü perşembeye gelemez, çarşamba nöbetçisidir. Geriye perşembe ve kantin Oğuz\'a kalır.'),
  ('“Bazı kuşlar uçamaz.” ve “Bütün kuşlar yumurtlar.” öncüllerinden kesin olarak hangi sonuç çıkar?', 'Yumurtlayan bazı canlılar uçamaz.', ['Uçamayan her canlı bir kuştur.', 'Yumurtlayan her canlı uçabilir.', 'Bazı kuşlar yumurtlamadan çoğalır.'], 'Uçamayan kuşlar aynı zamanda yumurtlayan canlılardır. Bu yüzden yumurtlayanlar arasında uçamayanlar bulunur.'),
  ('Bir şirkette bütün yöneticilerin İngilizce bildiği ve bütün yöneticilerin araba kullandığı biliniyor. Şirkette en az bir yönetici vardır. Buna göre hangisi kesinlikle doğrudur?', 'İngilizce bilenlerin bazıları araba kullanır.', ['İngilizce bilen herkes araba kullanır.', 'Araba kullanan herkesin yönetici olduğu anlaşılır.', 'İngilizce bilen herkes yöneticidir.'], 'Var olan her yönetici hem İngilizce bilir hem araba kullanır. Bu kişi, İngilizce bilip araba kullanan birine örnektir.'),
  ('Uydurma sözcüklerle kurulmuş şu öncüller veriliyor: “Bütün zorbiler kırmızıdır.” ve “Hiçbir trak zorbi değildir.” Bu iki öncülden traklar hakkında hangisi söylenebilir?', 'Trakların rengi bu öncüllerden çıkarılamaz.', ['Hiçbir trak kırmızı değildir.', 'Bütün traklar kırmızıdır.', 'Bazı trakların kesinlikle kırmızı olduğu söylenebilir.'], 'Kırmızı olanlar yalnızca zorbilerle sınırlı değildir. Traklar zorbi olmasa da kırmızı olabilir ya da olmayabilir.'),
  ('“Bütün sorular kolaydır.” ile “Hiçbir soru kolay değildir.” önermeleri arasındaki ilişki için hangisi doğrudur?', 'Birlikte doğru olamazlar ama birlikte yanlış olabilirler.', ['İki önerme aynı anda doğru olabilir.', 'Biri doğruysa öteki de doğru olmak zorundadır, ayrı düşünülemezler.', 'Biri yanlışsa öteki mutlaka doğru olmalıdır.'], 'Bu iki önerme karşıttır. Bazı sorular kolay, bazıları zorsa ikisi de yanlış olur; ama ikisinin aynı anda doğru olması mümkün değildir.'),
  ('“Bütün öğretmenler üniversite mezunudur. Bazı üniversite mezunları yüksek lisans yapmıştır. Hiçbir öğretmen emekli değildir.” öncüllerinden aşağıdakilerden hangisi kesin olarak çıkarılamaz?', 'Bazı öğretmenler yüksek lisans yapmıştır.', ['Hiçbir emekli kişinin öğretmen olmadığı anlaşılır.', 'Her öğretmen üniversiteyi bitirmiştir.', 'Emekli sayılan bir öğretmen yoktur.'], 'Yüksek lisans yapan üniversite mezunlarının öğretmen olup olmadığı belirtilmemiştir. Diğer yargılar öncüllerin doğrudan ya da çevrilmiş biçimleridir.'),
  ('Bir adada yaşayanlar ya doğrucudur (her zaman doğruyu söyler) ya da yalancıdır (her zaman yalan söyler). Asya “Bora doğrucudur.” derken Bora “Asya doğrucu değildir.” diyor. Bu konuşma için hangisi söylenebilir?', 'Böyle bir konuşma adada geçemez.', ['Asya doğrucu, Bora ise bir yalancıdır.', 'İkisi de birer yalancıdır.', 'Asya yalancı, Bora doğrucudur.'], 'Asya doğrucuysa Bora da doğrucudur, ama o zaman Bora\'nın sözü yanlış olur. Asya yalancıysa Bora yalancıdır, ama o zaman Bora\'nın sözü doğru çıkar. Her iki durum da çelişkilidir.'),
  ('Üç kişilik bir yarıştan önce Ali “Birinci olmayacağım.”, Banu “Birinci ben olacağım.”, Cem “Sonuncu olmayacağım.” demiştir. Yarış sonunda bu üç sözden yalnızca birinin doğru çıktığı görülmüştür. Yarışı kim kazanmıştır?', 'Ali', ['Banu', 'Cem', 'Belirlenemez'], 'Ali ile Banu\'nun sözleri aynı anda doğru olamaz ve ikisi de yanlışsa Ali birincidir. Ali birinci, Cem ikinci, Banu üçüncü olduğunda yalnızca Cem\'in sözü doğrudur; başka bir sıralama tek doğru koşulunu sağlamaz.'),
  ('Bir tavşan salı, perşembe ve cumartesi günleri hep yalan söyler; haftanın diğer günlerinde hep doğru söyler. Tavşan bir gün “Yarın yalan söyleyeceğim.” demiştir. Bu söz haftanın hangi günü söylenmiş olamaz?', 'Pazar', ['Pazartesi', 'Salı', 'Cuma'], 'Doğru günlerde sözün doğru olması için ertesi günün yalan günü olması, yalan günlerinde ise ertesi günün doğru günü olması gerekir. Pazar doğru günüdür ama ertesi pazartesi de doğru günüdür; söz pazar söylenemez.'),
  ('Bir yarışmanın kupası kaybolmuştur ve şüpheliler Kenan, Leman, Metin ve Nesrin\'dir. Kupayı alan yalan söylüyor, ötekiler doğruyu söylüyor. Kenan: “Leman ya da Metin aldı.” Leman: “Kenan almadı.” Metin: “Nesrin aldı.” Nesrin: “Ben almadım.” Kupayı kim almıştır?', 'Metin', ['Kenan', 'Leman', 'Nesrin'], 'Metin aldıysa Kenan, Leman ve Nesrin doğru, Metin yalan söyler; tutarlıdır. Diğer seçeneklerde suçsuzlardan en az biri yalan söylemiş olur.'),
  ('Bir adada yaşayanlar ya doğrucudur (her zaman doğruyu söyler) ya da yalancıdır (her zaman yalan söyler). Dört kişiden Ahu “Aramızda tam bir doğrucu var.”, Barış “Tam iki doğrucu var.”, Ceyda “Tam üç doğrucu var.”, Demir “Dördümüz de doğrucuyuz.” diyor. Buna göre hangisi kesinlikle doğrudur?', 'Barış, Ceyda ve Demir yalancıdır.', ['Ahu yalancıdır.', 'Aralarında tam iki doğrucu bulunmaktadır.', 'Demir doğrucudur.'], 'Sözler birbirini dışladığı için en çok biri doğrudur. Ahu doğrucuysa tutarlıdır; herkes yalancı olduğunda da çelişki çıkmaz. İki durumda da Barış, Ceyda ve Demir yalancıdır.'),
  ('Murat\'ın babası, Leyla\'nın babasının tek kardeşidir. Ayrıca Leyla\'nın annesi, Murat\'ın annesinin kız kardeşidir. Murat ile Leyla arasındaki akrabalık için hangisi doğrudur?', 'Hem amca hem teyze çocuklarıdır.', ['Yalnızca amca çocuklarıdır.', 'Yalnızca teyze çocuklarıdır.', 'Hem dayı hem de hala çocukları olarak akrabadırlar.'], 'Babaları kardeş olduğu için amca çocukları, anneleri kardeş olduğu için de teyze çocuklarıdır.'),
  ('Bir kodlu dilde “ak bulut geçti” = “fo ri ta”, “kara bulut geldi” = “mu ri sa”, “kara gece geldi” = “sa ne mu” olarak yazılıyor; sözcüklerin sırası karşılıklarıyla aynı olmayabilir. Aşağıdaki sözcüklerden hangisinin karşılığı kesin olarak bulunabilir?', 'gece', ['kara', 'geldi', 'ak'], 'İkinci ve üçüncü ifadede ortak olan “kara” ve “geldi” sözcükleri mu ile sa\'ya karşılık gelir ama hangisinin hangisi olduğu ayrılamaz. Üçüncü ifadede geriye kalan “gece” ise kesinlikle ne\'dir.'),
  ('Düzenli spor yapan çocukların daha mutlu olduğu gözlenmiş ve bir uzman sporun çocukları mutlu ettiği sonucuna varmıştır. Hangisi bu sonucu en çok zayıflatır?', 'Mutlu çocukların spor etkinliklerine katılmaya daha istekli olduğu bulunmuştur.', ['Spor yapan çocukların bir kısmının bireysel değil takım sporlarını tercih ettiği görülmüştür.', 'Araştırmaya farklı okullardan çok sayıda çocuk katılmıştır.', 'Çocuklar en çok hafta sonları spor yapmaktadır.'], 'Bu bilgi ilişkinin tersine işleyebileceğini gösterir: spor mutluluğu değil, mutluluk spor yapmayı getiriyor olabilir.'),
  ('“Takımımızdaki her oyuncu kendi mevkisinde çok iyidir; bu yüzden takımımız da kesinlikle çok iyi bir takımdır.” sözündeki hata nasıl adlandırılır?', 'Birleştirme hatası', ['Bölme hatası', 'Kumarbaz yanılgısı', 'Geleneğe ve alışkanlığa başvurma'], 'Parçaların her birinin sahip olduğu özelliğin bütüne de geçeceği varsayılmıştır. Uyum sağlayamayan iyi oyuncular zayıf bir takım oluşturabilir.'),
  ('“Bu üniversite ülkenin en iyi üniversitesidir; demek ki orada okuyan her öğrenci çok başarılıdır.” sözündeki akıl yürütme hatası hangisidir?', 'Bölme hatası', ['Birleştirme hatası', 'Çoğunluğa başvurma', 'Yanlış neden'], 'Bütüne ait bir özelliğin, bütünün her parçasında da bulunduğu sanılmıştır.'),
  ('“Her yasa bir yasa koyucuyu gerektirir. Yerçekimi bir doğa yasasıdır. Öyleyse yerçekimi yasasını koyan biri vardır.” akıl yürütmesindeki temel kusur nedir?', '“Yasa” sözcüğü iki farklı anlamda kullanılmıştır.', ['Öncüllerin sayısı sonuca ulaşmak için yetersizdir.', 'Sonuç, öncüllerden biriyle aynı şeyi söylemektedir.', 'Bir uzmanın görüşüne kanıt yerine başvurulmuştur.'], 'İlk öncülde yasa “insanların koyduğu kural”, ikincide “doğadaki düzenlilik” anlamındadır. Anlam kaydığı için sonuç geçersizdir (çok anlamlılık hatası).'),
  ('Bir minibüste ön ve arka olmak üzere iki sıra, her sırada da sol, orta ve sağ olmak üzere üç koltuk vardır. Aras, Banu, Cem, Duru, Ebru ve Fatih yerleşiyor. Aras ön sıradadır ve Banu onun tam arkasında oturur. Cem orta koltuklardan birindedir. Duru, Cem ile aynı sırada değildir. Ebru arka sıranın sağındadır. Fatih sol koltuklardan birinde oturmaz. Buna göre hangisi kesinlikle doğrudur?', 'Fatih ön sırada oturur.', ['Cem arka sırada oturur.', 'Duru ön sıranın ortasında oturur.', 'Fatih ön sıranın sağ koltuğunda oturur.'], 'Arka sırada Banu solda, Ebru sağdadır; arka ortaya Fatih oturamaz, çünkü o zaman Duru ile Cem\'in ikisi de ön sıraya kalırdı. Bu yüzden Fatih her durumda ön sıradadır; sağda mı ortada mı olduğu ise belirsizdir.'),
  ('Üst, orta ve alt olmak üzere üç rafın her birine ikişer kitap konacaktır: kimya, müzik, roman, sözlük, tarih ve zooloji. Kimya ile müzik aynı raftadır. Roman üst rafta değildir. Sözlük, tarih kitabının hemen bir üst rafındadır. Zooloji alt rafa konmamıştır. Buna göre hangisi kesinlikle doğrudur?', 'Sözlük ile zooloji aynı raftadır.', ['Kimya kitabı üst raftadır.', 'Roman, rafların ortasındaki rafta yer alır.', 'Tarih kitabı alt raftadır.'], 'Sözlük-tarih ikilisi üst-orta ya da orta-alt raflara düşer. Her iki durumda da sözlüğün yanında kalan tek uygun kitap zoolojidir; diğer kitapların rafları duruma göre değişir.'),
  ('Bir otoparkta yan yana beş park yerine soldan sağa kırmızı, beyaz, siyah, gri ve mavi birer araç park etmiştir. Kırmızı ile beyaz araç yan yanadır. Siyah araç gri aracın solundadır. Mavi araç uçlardan birindedir. Gri araç en sağda değildir. Beyaz araç ortadaki yerde değildir. Buna göre aşağıdakilerden hangisi olamaz?', 'Siyah araç soldan dördüncü yerdedir.', ['Kırmızı araç en sağdaki park yerinde durmaktadır.', 'Beyaz araç en soldaki yerdedir.', 'Gri araç soldan ikinci yerdedir.'], 'Siyah dördüncü olursa gri, siyahın sağında yalnızca beşinci yere gidebilir; ama gri en sağda olamaz. Diğer üç durum için kurallara uyan dizilişler bulunur.'),
  ('Bir tavada aynı anda en çok iki ekmek dilimi kızartılabiliyor. Her dilimin iki yüzü de ayrı ayrı birer dakikada kızarıyor. Üç dilimin iki yüzünü de kızartmak en az kaç dakika sürer?', '3 dakika', ['4 dakika', '2 dakika', '6 dakika'], 'Altı yüzün her dakika ikisi kızartılabilir; en iyi plan bunu boşluksuz kullanır. 1. dakika: A ve B\'nin ön yüzü; 2. dakika: A\'nın arkası ve C\'nin önü; 3. dakika: B ile C\'nin arkası.'),
  ('Bir çekmecede 5 çift siyah ve 5 çift kahverengi eldiven karışık hâlde durmaktadır; her çiftin bir sağ, bir sol teki vardır. Karanlıkta en az kaç tek eldiven alınırsa aynı renkte bir sağ ve bir sol eldiven elde edilmesi garanti olur?', '11', ['3', '6', '10'], 'En kötü durumda önce bütün sol eldivenler, yani 5 siyah ve 5 kahverengi sol alınır. 11. eldiven bir sağ teki olur ve aynı renkteki bir sol tekle eşleşir.'),
  ('Bir savaşta geri dönen uçakların kanatlarında çok sayıda kurşun deliği görülmüş, motorlarında ise pek az delik bulunmuştur. Biri “Kanatları güçlendirelim.” diyor. Bu öneriye yöneltilebilecek en güçlü itiraz hangisidir?', 'Motorundan vurulan uçaklar geri dönemediği için incelenememiştir.', ['Kanatlar uçağın gövdesinden daha hafif bir malzemeden yapılmıştır.', 'Kanatların güçlendirilmesi uçakların maliyetini artıracaktır.', 'Uçakların bir kısmı yalnızca keşif amacıyla kullanılmıştır.'], 'Yalnızca dönebilen uçaklar incelendiği için örneklem yanlıdır. Az delik görülen motorlar, aslında vurulunca uçağın düştüğü yerler olabilir.'),
  ('Bir sınıftaki öğrencilerin tam yarısı kız, tam yarısı da gözlüklüdür. Buna göre aşağıdakilerden hangisi doğrudur?', 'Sınıfta gözlüklü kız hiç olmayabilir.', ['Sınıfta en az bir gözlüklü kız vardır.', 'Kızların tamamı gözlüklüdür.', 'Gözlüklülerin yarısı kızdır.'], 'Gözlüklülerin hepsi erkek olabilir; bu durumda kızlar ile gözlüklüler hiç kesişmez. Kesişimin büyüklüğü sıfırdan sınıfın yarısına kadar herhangi bir değer olabilir.'),
  ('Bir konserde Aslı, Burak, Cemre ve Doğan sırayla sahneye çıkıyor; her biri gitar, keman, piyano ya da flütten farklı birini çalıyor. Aslı piyano çalmaz. Keman çalan üçüncü sırada çıkar. Burak ilk sırada çıkar. Cemre flüt çalar. Doğan dördüncü sırada değildir. Aslı üçüncü sırada çıkmaz. Gitar çalan dördüncü sırada çıkmaz. Doğan hangi çalgıyı çalar?', 'Keman', ['Gitar', 'Piyano', 'Flüt'], 'Burak 1., Aslı ve Doğan 4. değildir; dördüncü Cemre\'dir. Aslı 3. olmadığından 2., Doğan 3. sıradadır. Üçüncü sırada keman çalındığına göre Doğan keman çalar.'),
  ('Ayla, Bora, Cansu, Deniz, Emre ve Fikret bir gezide üç tane iki kişilik odaya yerleşecektir. Ayla ile Bora aynı odada kalmayacaktır. Cansu, Deniz ya da Emre\'den biriyle kalacaktır. Fikret, Emre ile aynı odada olmayacaktır. Deniz, Ayla ile kalmayacaktır. Bora da Fikret ile kalmayacaktır. Buna göre hangisi kesinlikle doğrudur?', 'Ayla ile Fikret aynı odada kalır.', ['Bora ile Deniz aynı odada kalır.', 'Cansu ile Emre aynı odada kalır.', 'Bora ile Emre aynı odada kalır.'], 'Fikret, Emre ve Bora ile kalamaz. Cansu ile kalırsa Cansu\'nun koşulu bozulur; Deniz ile kalırsa Cansu Emre\'yle kalır ve Ayla ile Bora\'ya aynı oda kalır. Bu yüzden Fikret yalnızca Ayla ile kalabilir.'),
  ('Ali, Banu, Cem, Deniz, Ece, Fatih ve Gül arasından dört kişilik bir kurul kurulacaktır. Ali ile Banu\'dan tam biri kurulda olmalıdır. Cem ile Deniz birlikte kurulda yer alamaz. Ece kurula girerse Fatih de girmelidir. Kurulda Gül ya da Ali\'den en az biri bulunmalıdır. Kurallara uyan her kurulda kesinlikle kim bulunur?', 'Fatih', ['Gül', 'Ali', 'Ece'], 'Fatih olmazsa Ece de olamaz; geriye Ali/Banu\'dan biri, Cem/Deniz\'den biri ve Gül kalır; bu da en çok üç kişi eder. Dört kişilik kurul için Fatih şarttır.'),
  ('Bir sokakta 1\'den 5\'e numaralı yan yana beş ev kırmızı, yeşil, beyaz, sarı ve mavi boyalıdır; her evde farklı bir hayvan (kedi, köpek, kuş, balık, at) beslenir. Yeşil ev, beyaz evin hemen solundadır. Köpek kırmızı evde, balık yeşil evde beslenir. 3 numaralı evde kuş, 4 numaralı evde kedi vardır. Mavi ev 5 numaradır. At, sarı evin komşusu olan bir evde beslenir. At hangi renk evdedir?', 'Mavi', ['Sarı', 'Kırmızı', 'Beyaz'], 'Kuş 3\'te, kedi 4\'te olduğundan balıklı yeşil ev 1 ya da 2\'dir; yeşilin sağı beyaz olacağı için yeşil 2, beyaz 3\'tür. Kırmızı (köpek) 1\'e, sarı 4\'e düşer. At 5 numaralı mavi evdedir ve sarı evin komşusudur.'),
  ('“Ya otobüse yetişirim ya da taksiye binerim; belki ikisini de yaparım.” sözüyle mantıksal olarak aynı anlama gelen cümle hangisidir?', 'Otobüse yetişemezsem taksiye binerim.', ['Otobüse yetişirsem taksiye binmem.', 'Taksiye binersem otobüse yetişemem.', 'Otobüse yetişirsem taksiye de binerim.'], '“p veya q” önermesi, “p değilse q” önermesine denktir: otobüs kaçarsa geriye taksi kalır. Diğer cümleler ise bir seçeneğin diğerini dışladığını ya da gerektirdiğini söyler.'),
  ('“Erken kalkarsam koşuya çıkarım.” önermesine mantıksal olarak denk olan hangisidir?', 'Ya erken kalkmam ya da koşuya çıkarım.', ['Ya erken kalkarım ya da koşuya çıkarım.', 'Koşuya çıkarsam erken kalkmış olurum.', 'Erken kalkmazsam koşuya çıkmam.'], '“p ise q” önermesi, “p değil veya q” ile denktir: ya koşul gerçekleşmez ya da sonuç gerçekleşir.'),
  ('“Her öğrencinin en az bir kitabı vardır.” önermesinin değillemesi aşağıdakilerden hangisidir?', 'Hiç kitabı olmayan en az bir öğrenci vardır.', ['Hiçbir öğrencinin kitabı yoktur.', 'Bazı öğrencilerin birden çok kitabı vardır.', 'Her öğrencinin yalnızca bir kitabı vardır.'], '“Herkes için en az bir” yargısını çürütmek için kitapsız tek bir öğrenci yeterlidir. Bütün öğrencilerin kitapsız olması gerekmez.'),
  ('Şu bilgi doğrudur: “Ayşe gelirse, Burak geldiği takdirde Cem de gelir.” Ayşe gelmiş, Cem ise gelmemiştir. Burak hakkında ne söylenebilir?', 'Burak gelmemiştir.', ['Burak gelmiştir.', 'Burak\'ın gelip gelmediği bilinemez.', 'Burak, Cem\'den önce gelmiştir.'], 'Ayşe geldiğine göre “Burak gelirse Cem gelir” kuralı geçerlidir. Cem gelmediğine göre Burak da gelmemiştir.'),
  ('29 harfli Türk alfabesinde harfler sondan başa numaralandırılıyor: Z=1, Y=2, V=3 ve bu şekilde A=29 oluyor. Bu şifreye göre ADA sözcüğü nasıl yazılır?', '29-25-29', ['1-5-1', '29-26-29', '29-24-29'], 'A en baştaki harf olduğu için 29 alır. D baştan 5. harftir; sondan sayınca 29 − 5 + 1 = 25 numarayı alır.'),
  ('Bir dizi şöyle kuruluyor: bir Y bir A, iki Y bir A, üç Y bir A ve her seferinde Y sayısı bir artıyor: Y A Y Y A Y Y Y A … Bu dizideki yedinci A harfi baştan kaçıncı sıradadır?', '35', ['33', '36', '28'], 'A harfleri 2, 5, 9, 14, 20, 27, 35. sıralara düşer; her A bir öncekinden bir fazla adım sonra gelir.'),
  ('“Bu telefonun pili öbür telefonunkinden büyük; o hâlde şarjı daha uzun dayanır.” akıl yürütmesi hangi varsayıma dayanır?', 'İki telefonun enerji tüketimi birbirine yakındır.', ['Büyük pilli telefonlar her zaman daha pahalıya satılmaktadır.', 'İki telefon da aynı firmanın aynı yıl ürettiği modellerdir.', 'Kullanıcıların çoğu telefonunu günde bir kez şarj etmektedir.'], 'Pil büyüklüğü tek başına süreyi belirlemez; telefon çok daha fazla enerji harcıyorsa büyük pil de erken biter. Sonuç, tüketimin benzer olduğu varsayımına dayanır.'),
  ('Birisi “Uzun boylu insanlar iş hayatında daha başarılıdır; çünkü büyük şirketlerin yöneticilerinin çoğu uzun boyludur.” diyor. Hangisi bu görüşü en çok zayıflatır?', 'Bu şirketlerin tüm çalışanlarının boy ortalaması yöneticilerinkiyle aynıdır.', ['Yöneticilerin çoğunun üniversite eğitimi aldığı bilinmektedir.', 'Bazı küçük şirketlerin yöneticileri de oldukça uzun boyludur.', 'Şirket yöneticileri genellikle uzun saatler çalışmak zorundadır.'], 'Çalışanların genelinde de boy aynıysa yöneticilerin uzun olması özel bir durum değildir; boy ile başarı arasında bir ilişki görülmez.'),
  ('Bir okul, yeni okuma programının öğrencilerin okuma becerisini geliştirdiğini göstermek istiyor. Bu iddiayı değerlendirmek için en çok hangi bilgiye ihtiyaç vardır?', 'Programa katılmayan benzer öğrencilerin aynı dönemdeki gelişimi', ['Programda kullanılan kitapların toplam sayfa sayısı ve basım yılları', 'Programı hazırlayan öğretmenlerin meslekte kaç yıl çalıştığı', 'Programa katılan öğrencilerin programı ne kadar eğlenceli bulduğu'], 'Öğrenciler zaten zamanla gelişir. Programın etkisini görmek için katılmayan benzer bir grupla karşılaştırma yapmak gerekir.'),
  ('A: “Hiçbir gerçek sporcu kahvaltıyı atlamaz.” B: “Ama Ali milli sporcu ve sık sık kahvaltıyı atlıyor.” A: “O zaman Ali gerçek bir sporcu değildir.” A\'nın son sözündeki hata nedir?', 'Karşı örneği, tanımı değiştirerek geçersiz saymak', ['Konuyu ilgisiz bir alana kaydırmak', 'Bir otoritenin sözüne kanıt yerine başvurmak', 'Olası seçenekleri yalnızca ikiye indirmek'], 'A, iddiasını çürüten örneği kabul etmek yerine “gerçek sporcu” tanımını keyfî biçimde daraltmıştır.'),
  ('Altı arkadaş boylarına göre uzundan kısaya sıralanıyor. Ayşe, Buse\'den uzundur. Cem ne en uzun ne de en kısadır. Dora, Cem\'den uzundur. Efe, Buse\'den kısadır. Fırat ikinci sıradadır. Buna göre hangisi kesinlikle doğrudur?', 'Efe grubun en kısasıdır.', ['Ayşe grubun en uzun kişisidir.', 'Cem sıralamada beşinci sıradadır.', 'Dora sıralamada üçüncü sıradadır.'], 'En kısa kişi Cem olamaz; Ayşe ve Dora\'nın altında birileri, Buse\'nin altında da Efe vardır. Altıncı sıraya yalnızca Efe uyar. Diğer yerler birden çok biçimde doldurulabilir.'),
  ('Gül, Hande, İlker, Jale ve Kaan bir yarışa katılmıştır. Hande, Gül\'den iki sıra sonra bitirmiştir. İlker, Jale\'den önce bitirmiştir. Kaan birinci olmuştur. Jale ile Hande art arda bitirmiştir. Buna göre hangisi kesinlikle doğrudur?', 'İlker ilk üç içinde bitirmiştir.', ['Gül yarışı ikinci sırada bitirmiştir.', 'Hande yarışta sonuncu olmuştur.', 'Jale yarışı dördüncü sırada bitirmiştir.'], 'Olası iki sıralama Kaan-Gül-İlker-Hande-Jale ve Kaan-İlker-Gül-Jale-Hande\'dir. İkisinde de İlker ikinci ya da üçüncüdür; diğer seçenekler yalnızca birinde doğrudur.'),
  ('Ali, Bora, Cem, Defne, Ece ve Fırat yuvarlak bir masanın çevresine eşit aralıklarla oturmuştur. Ali, Bora\'nın tam karşısındadır. Cem ile Defne yan yanadır. Ece, Ali\'nin yanındadır. Fırat, Cem\'in tam karşısındadır. Buna göre hangisi kesinlikle doğrudur?', 'Defne, Bora\'nın yanında oturur.', ['Cem, Ali\'nin tam karşısında oturur.', 'Ece, Fırat\'ın tam karşısında oturur.', 'Fırat, Ali\'nin hemen yanında oturur.'], 'Ece Ali\'nin bir yanını alınca Cem ile Defne\'ye Ali\'nin öbür yanı ve onun komşusu kalır; Cem Ali\'nin yanına, Defne de Bora\'nın yanına oturur. Fırat, Cem\'in karşısına yani Ece ile Bora\'nın arasına düşer.'),
  ('Bir ayda üç cuma günü çift sayılı tarihlere denk gelmiştir. Bu ayın 1. günü haftanın hangi günüdür?', 'Perşembe', ['Cuma', 'Çarşamba', 'Cumartesi'], 'Cumalar yedişer gün arayla gelir ve tek-çift sırayla değişir. Üç çift tarihli cuma için cumaların 2, 9, 16, 23 ve 30 olması gerekir; ayın 2\'si cuma ise 1\'i perşembedir.'),
  ('“Bazı kuşlar göç eder.” önermesinin doğru olduğu biliniyor. Buna göre “Bazı kuşlar göç etmez.” önermesi için hangisi söylenebilir?', 'Doğru da olabilir yanlış da.', ['Kesinlikle doğrudur.', 'Kesinlikle yanlıştır.', 'İlk önermeyle çelişir.'], 'Göç eden kuşların varlığı, göç etmeyen kuşların olup olmadığı hakkında bilgi vermez. Bütün kuşlar göç ediyor da olabilir.'),
  ('“Bütün tuvlar parlaktır.” ve “Bazı mekler tuv değildir.” öncülleri veriliyor. Meklerle ilgili hangisi söylenebilir?', 'Meklerin parlak olup olmadığı bu öncüllerden çıkmaz.', ['Bazı mekler parlak değildir.', 'Bütün mekler parlaktır.', 'Hiçbir mek parlak değildir.'], 'Tuv olmayan mekler parlak da olabilir, olmayabilir de; çünkü parlaklık yalnızca tuvlara özgü sayılmamıştır.'),
  ('Bir adada yaşayanlar ya doğrucudur (her zaman doğruyu söyler) ya da yalancıdır (her zaman yalan söyler). Aras “Üçümüzden en az ikisi doğrucudur.”, Bilge “Aras yalancıdır.”, Ceren “Aras ile Bilge aynı türdendir.” diyor. Bu üç kişiden kimler doğrucudur?', 'Yalnızca Bilge', ['Yalnızca Aras', 'Aras ile Ceren', 'Bilge ile Ceren'], 'Aras ile Bilge farklı türdendir, bu yüzden Ceren\'in sözü yanlıştır ve Ceren yalancıdır. O zaman en çok bir doğrucu vardır, Aras\'ın sözü yanlıştır; doğrucu yalnızca Bilge\'dir.'),
  ('Bir dolabı karıştıran kişi Arif, Burcu, Cenk ve Dilan\'dan biridir. Arif: “Ben yapmadım.” Burcu: “Cenk yaptı.” Cenk: “Arif ya da Burcu yaptı.” Dilan: “Ben yapmadım.” Dört sözden tam ikisi doğruysa dolabı kim karıştırmıştır?', 'Arif', ['Burcu', 'Cenk', 'Dilan'], 'Burcu ile Cenk\'in sözleri aynı anda doğru olamaz. Arif yaptıysa yalnızca Cenk ile Dilan doğru söyler. Diğer adaylar denendiğinde doğru söz sayısı ikiden farklı çıkar.'),
  ('Bir sınıfın beş saatlik programına matematik, Türkçe, fizik, tarih ve İngilizce birer saat yerleştirilecektir. Matematik fizikten önce olacak. Türkçe ile tarih arasında en az bir ders bulunacak. İngilizce üçüncü saatte olacak. Fizik son saate, tarih de ilk saate konmayacak. Buna göre hangisi kesinlikle doğrudur?', 'Fizik dördüncü saattedir.', ['Matematik günün ilk saatindedir.', 'Tarih günün son saatine konmuştur.', 'Türkçe ikinci saatte yapılmaktadır.'], 'Fizik son saat olamaz ve matematikten sonra gelmelidir; 3. saat İngilizcenin olduğundan fizik 2. ya da 4. saattedir. Fizik 2. olursa matematik 1. olur ve Türkçe ile tarih yan yana kalan 4-5. saatlere düşer; bu yasaktır. Fizik dördüncü saattedir.'),
  ('Ayten, Bülent ve Canan pazartesiden cumartesiye kadar her gün bir kişi olmak üzere nöbet tutacaktır. Her biri tam iki gün nöbet tutacak ve kimse art arda iki gün nöbetçi olmayacaktır. Ayten pazartesi, Bülent cuma nöbetçidir; Canan salı günü nöbet tutmaz. Cumartesi günü kim nöbet tutar?', 'Canan', ['Ayten', 'Bülent', 'Belirlenemez'], 'Salı Bülent\'tir (Ayten art arda olamaz, Canan salı tutmaz). Cumartesi cumadan sonra geldiği için Bülent olamaz. Ayten cumartesi tutarsa Canan\'ın iki günü çarşamba ve perşembeye, yani art arda günlere düşer; bu yüzden cumartesi Canan\'dır.'),
  ('Dört takımlı bir ligde her takım diğerleriyle birer kez oynamıştır; galibiyete 3, beraberliğe 1, yenilgiye 0 puan verilir. Lig sonunda takımlar 7, 5, 3 ve 1 puan toplamıştır. Kaç maç berabere bitmiştir?', '2', ['1', '3', '4'], '6 maç oynanmıştır. Her galibiyetli maç toplama 3, her beraberlik 2 puan ekler. Toplam 16 puan, 6 × 3 = 18\'den 2 eksik olduğundan 2 maç berabere bitmiştir.'),
  ('8 litrelik bir kap ağzına kadar su doludur; yanında boş 5 litrelik ve 3 litrelik iki kap vardır. Su yalnızca bir kaptan ötekine dökülerek (kap boşalana ya da öteki dolana kadar) taşınabiliyor. Kaplardan birinde tam 4 litre elde etmek için en az kaç dökme gerekir?', '6', ['5', '7', '8'], '8→5, 5→3, 3→8, 5→3, 8→5, 5→3 adımlarıyla 5 litrelik kapta 4 litre kalır. Daha kısa bir dökme sırası 4 litreyi oluşturamaz.'),
  ('30 öğrencili bir sınıfta öğrencilerin doğum ayları bilinmemektedir. Aynı ayda doğmuş öğrencilerin sayısı için kesin olarak söylenebilecek en büyük alt sınır kaçtır?', '3', ['2', '4', '5'], 'Öğrenciler 12 aya olabildiğince eşit dağıtılsa bile 12 × 2 = 24\'ten fazla öğrenci olduğu için en az bir aya 3 öğrenci düşer. 4 kişilik bir ay ise zorunlu değildir.'),
  ('Beş arkadaşın yaşları birbirinden farklı tam sayılardır. En büyükleri 20, en küçükleri 16 yaşındadır. Buna göre hangisi kesinlikle doğrudur?', 'Arkadaşlardan biri tam 18 yaşındadır.', ['Arkadaşların yaş ortalaması 18\'den büyüktür.', 'İki arkadaşın yaşları birbirine eşittir.', 'Arkadaşlardan ikisi 19 yaşındadır.'], '16 ile 20 arasında yalnızca beş farklı tam sayı vardır: 16, 17, 18, 19, 20. Beş farklı yaş bu değerlerin hepsini almak zorundadır.'),
  ('Masada 1\'den 5\'e kadar numaralı, hepsi kapalı beş kart vardır. Birinci kişi bütün kartları, ikinci kişi numarası 2\'nin katı olan kartları, üçüncü kişi 3\'ün katı olanları, dördüncü kişi 4\'ün katı olanları, beşinci kişi de 5\'in katı olanları çeviriyor. Sonunda kaç kart açık durur?', '2', ['1', '3', '5'], 'Bir kart, numarasının bölen sayısı kadar çevrilir. Yalnızca 1 ve 4\'ün bölen sayısı tektir; bu iki kart açık kalır.'),
  ('Bir adada yaşayanlar ya hep doğru ya da hep yalan söyler. Ada “Berk de Cansu da yalancıdır.”, Berk “Ada yalancıdır.”, Cansu “Berk doğrucudur.” diyor. Buna göre hangisi kesinlikle doğrudur?', 'Berk ile Cansu aynı türdendir.', ['Ada bir doğrucudur.', 'Üç kişinin de aynı türden olduğu kesindir.', 'Cansu bir yalancıdır.'], 'Cansu\'nun sözü nedeniyle Cansu ile Berk aynı türdendir. Ada doğrucuysa ikisi yalancı; Ada yalancıysa ikisi doğrucudur. Hangisinin geçerli olduğu bilinemez.'),
  ('Bir kişi bir merdivenin 1. basamağından 5. basamağına sabit hızla 8 saniyede çıkmaktadır. Aynı hızla 1. basamaktan 9. basamağa kaç saniyede çıkar?', '16', ['14', '18', '12'], '1\'den 5\'e dört basamak aralığı vardır, her biri 2 saniye sürer. 1\'den 9\'a sekiz aralık olduğundan süre 16 saniyedir.'),
  ('Bir ailedeki her kız çocuğunun erkek kardeş sayısı kız kardeş sayısına eşittir. Her erkek çocuğunun ise kız kardeş sayısı erkek kardeş sayısının iki katıdır. Bu ailede kaç çocuk vardır?', '7', ['5', '6', '8'], 'Kız sayısı k, erkek sayısı e olsun. Bir kız için e = k − 1, bir erkek için k = 2(e − 1) olur. Bu eşitlikleri sağlayan değerler k = 4, e = 3\'tür; toplam 7 çocuk.'),
  ('“Bütün fırlar dolgudur. Hiçbir dolgu sert değildir. Bazı kemler serttir.” öncüllerinden hangi sonuç kesinlikle çıkar?', 'Bazı kemler fır değildir.', ['Bütün kemlerin dolgu olduğu sonucu çıkar.', 'Hiçbir kem sert değildir.', 'Bazı fırlar serttir.'], 'Fırlar dolgu, dolgular da sert olmadığından hiçbir fır sert değildir. Sert olan kemler bu yüzden fır olamaz.'),
  ('Beş kişilik bir grupta en az üç kişi gözlüklüdür ve en fazla iki kişi kahverengi gözlüdür. Buna göre hangisi kesinlikle doğrudur?', 'Gözlüklü olup gözleri kahverengi olmayan en az bir kişi vardır.', ['Grupta kahverengi gözlü olan iki kişi vardır.', 'Her gözlüklünün gözleri kahverengidir.', 'Grupta gözlük takmayan en az iki kişinin bulunduğu kesin olarak bilinir.'], 'Gözlüklülerin en az üç, kahverengi gözlülerin en çok iki kişi olması, gözlüklülerden en az birinin kahverengi gözlü olmamasını zorunlu kılar.'),
  ('“Kar yağarsa okul tatil olur.” ve “Okul ancak kar yağarsa tatil olur.” cümleleri arasındaki mantıksal fark nedir?', 'İlki karı yeterli, ikincisi karı gerekli koşul sayar.', ['İki cümle mantıksal olarak tamamen aynı anlamı taşır, fark yoktur.', 'İlki karı gerekli, ikincisi karı yeterli koşul sayar.', 'İkinci cümle karın okulu hiç etkilemediğini söyler.'], '“-sa” yapısı yeterliliği bildirir: kar yağınca tatil olur. “Ancak … -sa” yapısı gerekliliği bildirir: tatil varsa kar yağmıştır.'),
  ('Bir araştırmacı yüzlerce veri arasından yalnızca kendi kuramına uyan birkaç örüntüyü sonradan seçip “Kuramım doğrulandı.” diyor. Bu davranıştaki temel sorun nedir?', 'Hedefi atıştan sonra çizmek, yani örüntüyü sonradan seçmek', ['Az sayıda kişinin görüşüne dayanarak bütün topluluk hakkında genelleme yapmak', 'Bir otoritenin sözünü kanıtın yerine koymak', 'Konuyu ilgisiz bir başka alana kaydırmak'], 'Örüntüler veriler toplandıktan sonra ve yalnızca uyanlar seçilerek belirlendiğinde rastlantısal benzerlikler kanıt gibi görünür. Buna Teksas nişancısı yanılgısı denir.'),
  ('Arda, Burak, Cenk ve Duygu bir sırada duruyor ve şu dört bilgi veriliyor: (1) Arda, Burak\'ın önündedir. (2) Cenk dördüncü sıradadır. (3) Duygu, Arda\'nın hemen arkasındadır. (4) Burak ikinci sırada değildir. Hangi bilgi çıkarılsa da sıralama yine tek biçimde belirlenebilir?', '4. bilgi', ['1. bilgi', '2. bilgi', '3. bilgi'], 'İlk üç bilgiyle Cenk 4., Arda-Duygu ikilisi Burak\'tan önce gelir ve sıra Arda, Duygu, Burak, Cenk olur; Burak zaten ikinci olamaz. Diğer bilgilerden biri çıkarılırsa birden çok sıralama mümkün hâle gelir.'),
  ('Ali, Banu, Cem, Deniz, Ece, Fatih, Gül ve Hakan dörder kişilik iki takıma ayrılacaktır. Ali ile Banu farklı takımlarda olacak. Cem ile Deniz aynı takımda olacak. Ece ile Fatih farklı takımlarda olacak. Gül ile Cem aynı takımda olmayacak. Ali\'nin takımı kaç farklı biçimde oluşturulabilir?', '4', ['2', '3', '6'], 'Ali\'nin takımına Cem-Deniz ikilisi girerse Gül ve Hakan karşıya geçer, takıma Ece ya da Fatih eklenir (2 yol). İkili girmezse takım Ali, Gül, Hakan ve Ece ya da Fatih\'ten oluşur (2 yol). Toplam 4.'),
  ('Ali, Banu, Cem, Deniz, Ece ve Fatih arasından üç kişilik bir kurul seçilecektir. Ali kurula girerse Banu da girmelidir. Cem ile Ece birlikte kurulda yer alamaz. Kurulda Deniz ya da Fatih\'ten en az biri bulunmalıdır. Bu koşullara uyan kaç farklı kurul oluşturulabilir?', '9', ['8', '10', '12'], 'Uygun kurullar şunlardır: ABD, ABF, BCD, BCF, BDE, BDF, BEF, CDF, DEF. Ali\'nin bulunduğu kurullarda Banu ile birlikte Deniz ya da Fatih olmalıdır.'),
  ('Bir adada her insan ya hep doğru ya hep yalan söyler. Asu “Bulut ile Cihan aynı türdendir.”, Bulut “Cihan bir yalancıdır.”, Cihan da “Asu doğrucudur.” diyor. Bu üç kişiden kimler doğrucudur?', 'Yalnızca Bulut', ['Yalnızca Asu', 'Asu ile Cihan', 'Bulut ile Cihan'], 'Cihan\'ın sözü nedeniyle Asu ile Cihan aynı türdendir. İkisi doğrucu olsaydı Bulut da Cihan\'la aynı türden yani doğrucu olurdu; ama Bulut Cihan\'a yalancı demektedir. İkisi yalancıdır ve doğrucu yalnızca Bulut\'tur.'),
  ('Ayla, Buse, Ceren, Doruk, Ece ve Ferhat bir sıraya diziliyor. Ayla, Buse\'den; Buse de Ceren\'den öndedir. Doruk ile Ece art arda durmaktadır. Ferhat üçüncü sıradadır. Doruk en başta değildir. Buna göre hangisi kesinlikle yanlıştır?', 'Ayla ikinci sıradadır.', ['Buse ikinci sıradadır.', 'Ceren en sondadır.', 'Ece en baştadır.'], 'Ayla ikinci olursa Buse ile Ceren dört, beş ya da altıncı yerlere geçer ve Doruk-Ece ikilisine yan yana iki boş yer kalmaz; ilk yere de Doruk gelemez. Diğer üç durum uygun dizilişlerde görülür.'),
  ('Ali, Bilge, Can ve Demet; mavi, yeşil, kırmızı ve sarı tişörtler giymiş ve futbol, basketbol, voleybol ile tenisten farklı birini oynuyor. Ali mavi giymez ve tenis oynamaz. Yeşil giyen tenis oynar. Bilge futbol oynar. Can sarı giyer. Demet voleybol oynamaz. Basketbol oynayan kırmızı giymez. Basketbol oynayan kişinin tişörtü hangi renktir?', 'Sarı', ['Mavi', 'Yeşil', 'Kırmızı'], 'Ali tenis ve futbol oynamaz; Demet de voleybol oynamaz. Yeşilli tenisçi Ali olamayacağı için Demet ya da Can\'dır; Can sarı olduğundan Demet yeşil ve tenisçidir. Ali voleybol, Can basketbol oynar; Can\'ın tişörtü sarıdır.'),
  ('Sekiz kişi yuvarlak bir masanın çevresine eşit aralıklarla oturmuştur. Emre, Ali\'nin tam karşısındadır. Banu, Ali\'nin yanındadır. Cem, Emre\'nin yanındadır. Deniz, Banu\'nun tam karşısındadır. Feyza, Cem\'in tam karşısındadır. Gizem, Deniz\'in yanındadır. Sekizinci kişi Hakan\'dır. Hakan\'ın iki yanında kimler oturur?', 'Banu ile Cem', ['Ali ile Feyza', 'Deniz ile Gizem', 'Emre ile Banu'], 'Banu Ali\'nin bir yanına oturunca Deniz onun karşısına, yani Emre\'nin bir yanına düşer; Cem Emre\'nin öbür yanına geçer. Gizem Deniz\'in yanına, Feyza da Cem\'in karşısına (Ali\'nin öbür yanına) oturur. Geriye kalan tek yer Banu ile Cem\'in arasıdır.'),
  ('Bir ayın ilk günü de son günü de cumartesiye denk gelmiştir. Bu ay kaç gün çekmektedir?', '29', ['28', '30', '31'], 'Aynı güne denk gelen iki tarih arasında 7\'nin katı kadar gün vardır. 1\'den 28 gün sonrası ayın 29\'udur; 30 ya da 31 gün çeken aylarda son gün cumartesi olamaz, 28 günlük bir ayın son günü de cumadır.'),
  ('Bir bilgi yarışmasına yedi farklı ülkeden toplam 50 kişi katılmıştır. Buna göre aynı ülkeden gelen yarışmacı sayısı için kesin olarak söylenebilecek en büyük alt sınır kaçtır?', '8', ['7', '9', '6'], 'Yarışmacılar ülkelere olabildiğince eşit dağıtılsa bile 7 × 7 = 49\'dan fazla kişi olduğu için en az bir ülkeden 8 kişi gelmiştir.'),
  ('“En az iki öğrenci derse geç kaldı.” önermesinin değillemesi aşağıdakilerden hangisidir?', 'En fazla bir öğrenci derse geç kaldı.', ['Hiçbir öğrenci derse geç kalmadı.', 'Tam olarak iki öğrenci derse geç kaldı.', 'En az iki öğrenci derse zamanında geldi.'], '“En az iki” yargısının olumsuzu, geç kalanların sayısının ikiden az, yani sıfır ya da bir olmasıdır.'),
  ('Bir firma “Ürünümüzü kullananların %80\'i ürünümüzden memnun.” diyor. Aşağıdakilerden hangisi bu iddianın güvenilirliğini en çok zayıflatır?', 'Ankete yalnızca ürünü bir yıldan uzun süredir kullanmaya devam edenler katılmıştır.', ['Ankete katılanların yaş ortalaması 35 civarındadır.', 'Firmanın aynı ürünün daha ucuz bir modelini de sattığı bilinmektedir.', 'Ankete katılanların yarısından fazlası kadındır.'], 'Memnun olmayanlar büyük olasılıkla ürünü bırakmıştır. Yalnızca kullanmaya devam edenlere sormak memnuniyeti olduğundan yüksek gösterir.'),
  ('“Bu fikir eskiden bir köy kahvesinde ortaya atılmış; bu yüzden bilimsel bir değeri olamaz.” sözündeki akıl yürütme hatası nedir?', 'Bir fikri ortaya çıktığı yer yüzünden reddetmek', ['Bir fikri çok kişi benimsediği için doğru saymak', 'Bir fikri kanıtlanamadığı için doğru kabul etmek', 'Bir fikrin bütününü parçalarından yargılamak'], 'Bir düşüncenin doğruluğu kaynağına değil kanıtlarına bağlıdır. Fikri kökeni yüzünden reddetmeye köken safsatası denir.'),
  ('31 gün çeken bir ayda beşer tane cuma, cumartesi ve pazar günü vardır. Bu ayın ilk günü haftanın hangi günüdür?', 'Cuma', ['Perşembe', 'Cumartesi', 'Pazar'], '31 gün dört hafta artı üç gündür; ayın ilk üç gününe denk gelen haftanın günleri beşer kez görülür. Bu üç gün cuma, cumartesi ve pazar olduğuna göre ay cuma başlar.'),
  ('Pınar, Rana, Selin, Tarık ve Volkan bir sıraya diziliyor. Pınar, Rana\'nın hemen önündedir. Selin, Tarık\'tan sonra gelir. Volkan ya en baştadır ya da en sondadır. Tarık ilk sırada, Rana da son sırada değildir. Buna göre hangisi kesinlikle doğrudur?', 'Selin ilk üç sırada yer almaz.', ['Volkan sıranın en sonundadır.', 'Tarık ikinci sırada durmaktadır.', 'Pınar sıranın en başındadır.'], 'Olası dizilişler Pınar-Rana-Tarık-Selin-Volkan, Volkan-Pınar-Rana-Tarık-Selin ve Volkan-Tarık-Pınar-Rana-Selin\'dir. Selin her durumda dördüncü ya da beşincidir.'),
];
